package com.example.examplemod.client.gui;

import com.example.examplemod.client.gui.fimgui.FimGfx;
import com.example.examplemod.client.gui.fimgui.FimUi;
import com.mojang.blaze3d.systems.RenderSystem;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.text.Text;
import net.minecraft.util.Identifier;
import org.lwjgl.glfw.GLFW;

import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.Map;

/**
 * Nexus Menu - generated by Fimgui for Minecraft 1.21.1 (Fabric, Yarn mappings).
 * Open it with: MinecraftClient.getInstance().setScreen(new NexusScreen());
 * The design is drawn by NexusMenu in design pixels and fitted into the window.
 */
public class NexusScreen extends Screen {
    public static final String MOD_ID = "examplemod";
    public final NexusMenu menu = new NexusMenu();
    private final FimUi ui = new FimUi();
    private float fit = 1, ox, oy;

    public NexusScreen() {
        super(Text.literal("Nexus Menu"));
    }

    @Override
    protected void init() {
        menu.anim.restart();
    }

    private void layout() {
        fit = Math.min(1f, Math.min((width - 16) / NexusMenu.WIDTH, (height - 16) / NexusMenu.HEIGHT));
        ox = (width - NexusMenu.WIDTH * fit) / 2;
        oy = (height - NexusMenu.HEIGHT * fit) / 2;
    }

    private double dx(double x) { return (x - ox) / fit; }
    private double dy(double y) { return (y - oy) / fit; }

    @Override
    public void render(DrawContext ctx, int mouseX, int mouseY, float delta) {
        renderBackground(ctx, mouseX, mouseY, delta);
        layout();
        Gfx g = new Gfx(ctx);
        ui.beginFrame(dx(mouseX), dy(mouseY), System.nanoTime() / 1e9);
        g.push();
        g.translate(ox, oy);
        g.scale(fit);
        menu.render(g, ui);
        ui.endFrame();
        g.pop();
    }

    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        if (button == 0) { ui.mx = dx(mouseX); ui.my = dy(mouseY); ui.down = true; ui.pressed = true; }
        return true;
    }

    @Override
    public boolean mouseReleased(double mouseX, double mouseY, int button) {
        if (button == 0) { ui.down = false; ui.released = true; }
        return true;
    }

    @Override
    public boolean mouseDragged(double mouseX, double mouseY, int button, double deltaX, double deltaY) {
        return true;
    }

    @Override
    public boolean mouseScrolled(double mouseX, double mouseY, double horizontalAmount, double verticalAmount) {
        ui.wheel += (float) verticalAmount;
        return true;
    }

    @Override
    public boolean charTyped(char chr, int modifiers) {
        if (ui.wantsKeyboard()) { ui.charTyped(chr); return true; }
        return super.charTyped(chr, modifiers);
    }

    @Override
    public boolean keyPressed(int keyCode, int scanCode, int modifiers) {
        if (ui.wantsKeyboard()) {
            if (keyCode == GLFW.GLFW_KEY_BACKSPACE) ui.keyBackspace();
            else if (keyCode == GLFW.GLFW_KEY_ENTER || keyCode == GLFW.GLFW_KEY_KP_ENTER) ui.keyEnter();
            else if (keyCode == GLFW.GLFW_KEY_ESCAPE) ui.keyEscape();
            return true;
        }
        return super.keyPressed(keyCode, scanCode, modifiers);
    }

    @Override
    public boolean shouldPause() {
        return false;
    }

    // Draws in design pixels: the matrix stack does the transform, a mirror of it is kept for scissor rectangles.
    private final class Gfx implements FimGfx {
        private static final float TTF_SIZE = 16f, VANILLA_SIZE = 9f;
        private final DrawContext c;
        private float tx, ty, s = 1;
        private final ArrayDeque<float[]> stack = new ArrayDeque<>();

        Gfx(DrawContext c) { this.c = c; }

        @Override public void push() { c.getMatrices().push(); stack.push(new float[] { tx, ty, s }); }
        @Override public void pop() { c.getMatrices().pop(); float[] t = stack.pop(); tx = t[0]; ty = t[1]; s = t[2]; }
        @Override public void translate(float x, float y) { c.getMatrices().translate(x, y, 0f); tx += x * s; ty += y * s; }
        @Override public void scale(float k) { c.getMatrices().scale(k, k, 1f); s *= k; }

        @Override public void fill(float x0, float y0, float x1, float y1, int argb) {
            if ((argb >>> 24) == 0 || x1 <= x0 || y1 <= y0) return;
            c.getMatrices().push();
            c.getMatrices().translate(x0, y0, 0f);
            c.getMatrices().scale(x1 - x0, y1 - y0, 1f);
            c.fill(0, 0, 1, 1, argb);
            c.getMatrices().pop();
        }

        private final Map<String, Identifier> ids = new HashMap<>();
        private Identifier id(String path) { return ids.computeIfAbsent(path, p -> Identifier.of(MOD_ID, p)); }

        @Override public void texture(String path, int texW, int texH, float x0, float y0, float x1, float y1, float alpha) {
            if (alpha <= 0.004f) return;
            RenderSystem.enableBlend();
            c.setShaderColor(1f, 1f, 1f, Math.min(1f, alpha));
            c.getMatrices().push();
            c.getMatrices().translate(x0, y0, 0f);
            c.getMatrices().scale((x1 - x0) / texW, (y1 - y0) / texH, 1f);
            c.drawTexture(id(path), 0, 0, texW, texH, 0f, 0f, texW, texH, texW, texH);
            c.getMatrices().pop();
            c.setShaderColor(1f, 1f, 1f, 1f);
            RenderSystem.disableBlend();
        }

        private Text styled(String str, String fontId) {
            return fontId == null ? Text.literal(str) : Text.literal(str).styled(st -> st.withFont(id(fontId)));
        }

        @Override public void text(String str, float x, float y, float size, int argb, String fontId) {
            if ((argb >>> 24) < 4 || str.isEmpty()) return;
            float k = size / (fontId == null ? VANILLA_SIZE : TTF_SIZE);
            c.getMatrices().push();
            c.getMatrices().translate(x, y + size * 0.12f, 0f);
            c.getMatrices().scale(k, k, 1f);
            c.drawText(textRenderer, styled(str, fontId), 0, 0, argb, false);
            c.getMatrices().pop();
        }

        @Override public float textWidth(String str, float size, String fontId) {
            return textRenderer.getWidth(styled(str, fontId)) * size / (fontId == null ? VANILLA_SIZE : TTF_SIZE);
        }

        @Override public void scissor(float x0, float y0, float x1, float y1) {
            c.enableScissor(Math.round(tx + x0 * s), Math.round(ty + y0 * s), Math.round(tx + x1 * s), Math.round(ty + y1 * s));
        }

        @Override public void endScissor() { c.disableScissor(); }
    }
}
